package fleetflow;
import java.util.*;
public class Module2 {
    public static void menu(Scanner sc){while(true){System.out.println("\n--- MODULE 2: STRING ALGORITHMS ---\n1. Naive pattern search\n2. KMP search\n3. Z-function\n4. Rabin-Karp double hash\n5. Edit-distance spelling correction\n0. Back");int c=Util.readInt(sc,"Choice: ");if(c==0)return;String s,p;switch(c){case 1:s=Util.readLine(sc,"Text: ");p=Util.readLine(sc,"Pattern: ");System.out.println("Matches at: "+naive(s,p));break;case 2:s=Util.readLine(sc,"Text: ");p=Util.readLine(sc,"Pattern: ");System.out.println("Matches at: "+kmp(s,p));break;case 3:s=Util.readLine(sc,"String: ");System.out.println("Z array: "+Arrays.toString(zFunction(s)));break;case 4:s=Util.readLine(sc,"Text: ");p=Util.readLine(sc,"Pattern: ");System.out.println("Matches at: "+rabinKarp(s,p));break;case 5:s=Util.readLine(sc,"Misspelt word: ");String[] dict={"shipment","delivery","logistics","vehicle","warehouse","destination","tracking","dispatch","customer","package"};String best="";int d=Integer.MAX_VALUE;for(String w:dict){int x=editDistance(s.toLowerCase(),w);if(x<d){d=x;best=w;}}System.out.println("Suggested: "+best+" (edit distance "+d+")");break;default:System.out.println("Invalid choice.");}}}
    public static List<Integer> naive(String s,String p){List<Integer>r=new ArrayList<>();if(p.isEmpty()){r.add(0);return r;}for(int i=0;i+p.length()<=s.length();i++)if(s.regionMatches(i,p,0,p.length()))r.add(i);return r;}
    public static List<Integer> kmp(String s,String p){List<Integer>r=new ArrayList<>();if(p.isEmpty()){r.add(0);return r;}int[] l=prefix(p);for(int i=0,j=0;i<s.length();){if(s.charAt(i)==p.charAt(j)){i++;j++;if(j==p.length()){r.add(i-j);j=l[j-1];}}else if(j>0)j=l[j-1];else i++;}return r;}
    private static int[] prefix(String p){int[] l=new int[p.length()];for(int i=1,j=0;i<p.length();i++){while(j>0&&p.charAt(i)!=p.charAt(j))j=l[j-1];if(p.charAt(i)==p.charAt(j))j++;l[i]=j;}return l;}
    public static int[] zFunction(String s){int n=s.length();int[] z=new int[n];for(int i=1,l=0,r=0;i<n;i++){if(i<=r)z[i]=Math.min(r-i+1,z[i-l]);while(i+z[i]<n&&s.charAt(z[i])==s.charAt(i+z[i]))z[i]++;if(i+z[i]-1>r){l=i;r=i+z[i]-1;}}if(n>0)z[0]=n;return z;}
    public static List<Integer> rabinKarp(String s,String p){List<Integer>r=new ArrayList<>();int n=s.length(),m=p.length();if(m==0){r.add(0);return r;}if(m>n)return r;long b=257,mod1=1_000_000_007L,mod2=1_000_000_009L,h1=0,h2=0,p1=0,p2=0,pow1=1,pow2=1;for(int i=0;i<m;i++){h1=(h1*b+s.charAt(i))%mod1;h2=(h2*b+s.charAt(i))%mod2;p1=(p1*b+p.charAt(i))%mod1;p2=(p2*b+p.charAt(i))%mod2;if(i<m-1){pow1=pow1*b%mod1;pow2=pow2*b%mod2;}}for(int i=0;i<=n-m;i++){if(h1==p1&&h2==p2&&s.regionMatches(i,p,0,m))r.add(i);if(i<n-m){h1=(h1-(s.charAt(i)*pow1)%mod1+mod1)%mod1;h1=(h1*b+s.charAt(i+m))%mod1;h2=(h2-(s.charAt(i)*pow2)%mod2+mod2)%mod2;h2=(h2*b+s.charAt(i+m))%mod2;}}return r;}
    public static int editDistance(String a,String b){int[][]d=new int[a.length()+1][b.length()+1];for(int i=0;i<=a.length();i++)d[i][0]=i;for(int j=0;j<=b.length();j++)d[0][j]=j;for(int i=1;i<=a.length();i++)for(int j=1;j<=b.length();j++)d[i][j]=Math.min(Math.min(d[i-1][j]+1,d[i][j-1]+1),d[i-1][j-1]+(a.charAt(i-1)==b.charAt(j-1)?0:1));return d[a.length()][b.length()];}
}
